  "dbdump.toggle": "Database dump before each backup",
  "dbdump.toggleHint": "BombVault recognised this container as a {engine} database. Before each backup it asks the running server for a full SQL dump and stores it as a restore point of its own, straight into the backup repository, without writing a file to your disks. A restore uses the files backup taken after the container stops; the dump is a second copy you can download or import. A failed dump never fails the backup; it shows up as a failed run of its own.",
  "dbdump.toggleHintLabel": "The container label bombvault.dbdump switches the dump on for this {engine} database. Before each backup it asks the running server for a full SQL dump and stores it as a restore point of its own. A failed dump never fails the backup; it shows up as a failed run of its own.",
  "dbdump.toggleHintOnlyCopy": "Before each backup BombVault asks this running {engine} server for a full SQL dump and stores it as a restore point of its own. For this container the dump is the only consistent copy of the database: its data folder is either copied while the server runs or not in any backup. Keep the dump on. A failed dump never fails the backup; it shows up as a failed run of its own.",
  "dbdump.toggleHintUnknown": "Before each backup BombVault asks this running {engine} server for a full SQL dump and stores it as a restore point of its own. Where this container keeps its data folder could not be determined, so whether the files backup holds a copy you can start from is unknown. The dump is the copy you can count on. Keep it on. A failed dump never fails the backup; it shows up as a failed run of its own.",
  "dbdump.lookalikeHint": "This container looks like a {engine} database, but its image is not one BombVault knows for sure. Switch the dump on if it is one; if the dump then fails, the image does not follow the usual settings and you can switch it off again.",
  "dbdump.engineLabel": "Database type",
  "dbdump.labelOff": "Switched off by the container label bombvault.dbdump=false.",
  "dbdump.globalOff": "Automatic database dumps are switched off for all containers in Settings, General.",
  "dbdump.offConfirmLive": "Switch off the dump for this database? Its data folder is copied while the server runs, so without the dump no consistent copy of it exists.",
  "dbdump.offConfirmNone": "Switch off the dump for this database? Its data folder is not in any backup, so without the dump nothing of it is saved.",
  "dbdump.offConfirmUnknown": "Switch off the dump for this database? BombVault could not determine where its data folder is, so whether any backup holds a copy you can start from is unknown.",
  "dbdump.coverageStopped": "Data folder: saved while the container is stopped.",
  "dbdump.coverageLive": "Data folder: copied while the server runs. The dump is the consistent copy.",
  "dbdump.coverageNone": "Data folder: not in any backup. The dump is the only copy.",
  "dbdump.coverageUnknown": "Data folder: could not be determined. Keep the dump on.",
  "dbdump.coverageHint": "A database writes to its files all the time. A copy of those files is only reliable when the server is stopped while it is taken, which BombVault does for folders in the container's backup. Folders in a compose project or a folder set are copied while the server runs, and folders outside appdata are not copied at all. In those cases the dump is what you would restore from.",
  "dbdump.hookOverlap": "The pre-backup command of this container already dumps a database. Switch one of the two off, or the database is dumped twice.",
  "dbdump.lastLine": "Last dump: {when}, {result}",
  "dbdump.noDumpYet": "No dump yet. The first one runs with the next backup.",
  "dbdump.resultCancelled": "cancelled",
  "dbdump.settingFailed": "The database dump setting could not be saved.",
  "dbdump.progress": "Dumping the database: {bytes}",
  "dbdump.busyDumping": "Dumping the database...",
  "dbdump.busySaving": "Saving the database dump...",
  "dbdump.busyImporting": "Importing the database dump...",
  "dbdump.updateWarn": "This is a database. An image update can move it to a new major version that refuses its old data folder. The dump taken just before the update can then be imported into the new version from the Backups panel.",
  "dbdump.updateWarnSameMajor": "This is a database. An image update can move it to a new major version. MySQL and MariaDB import a dump only into the major version it came from, so if the new version cannot use the old data folder, roll the image back to the previous version and import the dump taken just before the update there.",
  "dbdump.stackRestoreWarn":
    "one=The data of {names} is copied while the stack runs. After the restore, import its latest database dump before you use the app.|other=The data of {names} is copied while the stack runs. After the restore, import their latest database dump before you use the apps.",
  "dbdump.introNotice":
    "one=BombVault dumps the databases it recognises before each backup, as restore points of their own. Recognised here: {n} database, {name}. You can switch this off per container on its card or for all containers in Settings.|other=BombVault dumps the databases it recognises before each backup, as restore points of their own. Recognised here: {n} databases, the first is {name}. You can switch this off per container on its card or for all containers in Settings.",
  "dbdump.introDismiss": "Got it",
  "dbdump.fixAuth": "Check the password variables on the database container itself (for example POSTGRES_PASSWORD, MARIADB_ROOT_PASSWORD or MYSQL_ROOT_PASSWORD, or their _FILE versions). The dump uses exactly those.",
  "dbdump.fixPrivileges": "The dump could only log in as the app user, which lacks a right the dump needs. Give the container a real root password instead of a random one.",
  "dbdump.fixUnreachable": "The database server did not answer on its local socket. Check the container's log; it may still be starting or crashed.",
  "dbdump.fixNotRunning": "The container was paused or restarting when the backup ran. If it keeps restarting, check its log.",
  "dbdump.fixNoClient": "The image has no dump tool. Use the official image, or switch the dump off for this container.",
  "dbdump.fixSecret": "A password file named in a _FILE variable could not be read by the container's user. Check the path and its permissions.",
