  "dbdump.listTitle": "Database dumps",
  "dbdump.listHint": "Each dump is a full SQL export taken from the running database just before its backup. BombVault never loads a dump back by itself: restoring the container restores its files, and when those were saved with the container stopped they are the newer copy. Use a dump when those files cannot be used: they were copied while the server ran or not at all, the database moved to a new major version, or the data folder is damaged. Import puts the dump into a freshly started, empty database and keeps the old data folder next to it. A complete .sql file ends with a \"complete\" comment line.",
