  // MCP server: the key lifecycle, the client snippets and the certificate
  // of the address the operator opened BombVault at.
  "mcp.title": "MCP server",
  "mcp.hint": "Lets AI assistants such as Claude read the backup status of this server, start backups and cancel the backups they started, through the Model Context Protocol. Restores, deletions and settings stay in this web interface.",
  "mcp.statusOff": "Off: no key exists",
  "mcp.statusOn": "one=On, {n} active key|other=On, {n} active keys",
  "mcp.statusNoneWorks": "Off: none of the keys works",
  "mcp.noPasswordWarning": "No login password is set, so this web interface is open to everyone on your network, and anyone who can open it can also create a key.",
  "mcp.setPassword": "Set a login password",
  "mcp.needsPasswordForHost": "This page was opened as {host}. Without a login password, keys can only be created and replaced from an IP address or a local name such as tower or tower.local, so that no web page on the internet can create one. Setting a login password lifts that restriction for this address. You can also open BombVault by its local address.",
  "mcp.restoreRevokedNotice": "Restoring the configuration revoked every MCP key. Create new keys for your assistants.",
  "mcp.appKeyChanged": "APP_KEY has changed since these keys were created, so they no longer work. Replace each key and update your assistants.",
  "mcp.keyUnusable": "No longer valid after the APP_KEY change",
  "mcp.loadFailed": "The MCP keys could not be loaded",
  "mcp.endpointLabel": "Endpoint",
  "mcp.endpointHint": "The address your assistant connects to. It speaks Streamable HTTP and expects a key in the Authorization or X-API-Key header; there is no OAuth sign-in.",
  "mcp.newKey": "New key",
  "mcp.labelLabel": "Key name",
  "mcp.labelPlaceholder": "Claude Code on the laptop",
  "mcp.allowStart": "Allow starting backups",
  "mcp.allowStartHint": "With this on, the assistant can start a backup of one item, of a whole domain or of Backup Everything, and cancel the backups it started: at most {n} per hour, {minutes} minutes apart for the same item and {perDay} per item a day. A backup stops running containers until it finishes. With it off, the key can only read.",
  "mcp.createKey": "Create key",
  "mcp.created": "Key created",
  "mcp.labelInvalid": "Give the key a name of up to 64 characters.",
  "mcp.labelTaken": "An active key already has this name.",
  "mcp.limitReached": "one=There is already {n} active key. Revoke it before creating another.|other=There are already {n} active keys. Revoke one before creating another.",
  "mcp.newKeyTitle": "Your new key",
  "mcp.showOnce": "Copy it now. BombVault keeps only a fingerprint of it and cannot show it again.",
  "mcp.copyKey": "Copy key",
  "mcp.dismissKey": "I have copied it",
  "mcp.snippetsLabel": "Connect a client",
  "mcp.snippetOther": "Other clients",
  "mcp.snippetClaudeCodeHint": "Run this once in a terminal. Claude Code keeps the key in your user configuration, not in a project file. Check the connection with /mcp inside Claude Code.",
  "mcp.snippetShellHistory": "The command contains the key, and your shell may keep it in its history. The documentation shows a form without that.",
  "mcp.snippetDesktopHint": "Add this entry inside \"mcpServers\" in claude_desktop_config.json (in Claude Desktop: Settings, Developer, Edit Config), then restart Claude Desktop. It needs Node.js, because mcp-remote connects the desktop app to this server.",
  "mcp.snippetOtherHint": "Any client that speaks Streamable HTTP works. Send the key as Authorization: Bearer or as X-API-Key.",
  "mcp.snippetOtherCert": "The client also has to trust bombvault-cert.pem. Download it with the button next to the endpoint.",
  "mcp.copySnippet": "Copy snippet",
  "mcp.tlsHint": "Claude Code and Claude Desktop only connect over a certificate they trust. With BombVault's own certificate, add this address to it in this card and download it; the snippets then point Node.js at that file. A reverse proxy or Tailscale with a trusted certificate works without that step. HTTP_ONLY switches the whole web interface to plain HTTP, needs a change to the container settings and sends the key unencrypted. Never turn certificate checks off. Connectors added in Claude's own settings do not work with BombVault keys, because they sign in through OAuth, which BombVault does not offer.",
  "mcp.privacyHint": "What the assistant reads, such as item names, run history, error messages and unusual backups, is sent to the AI provider behind it. BombVault removes host paths, repository locations and credentials before anything leaves.",
  "mcp.certNotForThisAddress": "BombVault's certificate does not name {host}, so assistants will refuse to connect to this address. Add the address to the certificate, then download it for the snippets.",
  "mcp.certOwnNotForThisAddress": "Your certificate does not name {host}, so assistants will refuse to connect to this address. Connect through a name the certificate covers.",
