  "nav.anomalies": "Anomalies",
  "anomaly.navCountAria": "Open critical and warning anomalies: {n}",
  "anomaly.title": "Anomalies",
  "anomaly.cardHint": "BombVault compares every backup of an item with the ones before it and names what does not fit: much more new data than usual, most of the data rewritten, a source that shrank or grew sharply, a database dump that shrank, a backup that suddenly takes far longer, repeated failures, a restore check that stopped passing, and a disk that will soon be full. Most checks need 10 backups of an item first. A ZFS item is checked dataset by dataset, so a child dataset that was emptied shows even in a large tree.",
