  "offsite.wizard.passwordWarning": "Dieses Passwort wird nur EINMAL angezeigt und von BombVault nicht gespeichert. Jetzt sichern. Es wird für die Zugangsdaten unten benötigt und kann nicht wiederhergestellt werden.",
  "offsite.wizard.tlsNote": "Dieses Rezept nutzt einfaches HTTP, auf einem vertrauenswürdigen LAN oder VPN unproblematisch. Ist die Storage-Box über das Internet erreichbar, stelle rest-server hinter HTTPS (einen TLS-Reverse-Proxy), damit die Repository-Zugangsdaten nicht im Klartext übertragen werden.",
  "offsite.wizard.password": "Erzeugtes Passwort (sichern)",
  "offsite.wizard.passwordInfo": "Ein Geheimnis in zwei Formen. Der Klartext oben gehört in das REST-Passwort dieses Ziels, hier auf dieser Kiste. Die Rezepte darunter tragen dasselbe Passwort schon gehasht, in der Zeile, die an .htpasswd anhängt, und diese Zeile gehört auf die Speicherkiste. Du musst selbst nichts hashen.",
  "offsite.wizard.repoUrlInfo": "Der erste Teil des Pfads ist der Benutzer, kein Ordner: rest:http://kiste:8000/benutzer/repository. Der erzeugte Server liefert jedem Benutzer nur seinen eigenen Pfad, ein fehlender Benutzer antwortet also auch mit richtigem Passwort mit 401.",
