  "coverage.hint": "Alles auf diesem Server, das kein automatisches Backup erfasst. Die Karte darüber sagt, ob die geplanten Backups pünktlich liefen; diese Karte zeigt, was gar nicht eingeplant ist, und das zeigt sonst keine Seite. Eine Backup-Art, die du abgeschaltet hast, wird hier nicht mitgezählt. ZFS-Datasets, die du nicht hinzugefügt hast, werden ebenfalls nicht gezählt; die ZFS-Seite listet sie auf.",
