  // Pre/post-backup hooks
  "hooks.title": "Backup-Hooks",
  "hooks.hint": "Befehle laufen im Container mit sh -c. Der Pre-Befehl läuft vor dem Backup; nutze ihn, um Daten vorzubereiten, die mitgesichert werden sollen, etwa einen Cache auf die Platte schreiben zu lassen. Erkannte Datenbanken werden automatisch gedumpt und brauchen dafür keinen Hook. Schlägt der Pre-Befehl fehl, wird das Backup abgebrochen. Der Post-Befehl läuft, nachdem der Container wieder gestartet wurde, und sein Fehler wird nur geloggt. Hooks führen nur Befehle aus, sie fügen dem Backup keine zusätzlichen Ordner hinzu.",
  "hooks.pre": "Pre-Backup-Befehl",
  "hooks.post": "Post-Backup-Befehl",
  "folders.title": "Gesicherte Ordner",
  "folders.hint": "Wähle, welche gemappten Ordner dieses Containers gesichert werden. Der appdata-Ordner ist standardmäßig ausgewählt. Hake weitere an, um sie einzuschließen, oder füge einen eigenen Pfad unterhalb des Host-Mounts hinzu. Einen Haken überall zu entfernen ist blockiert; nutze Auswahl zurücksetzen, um zum automatischen appdata-Standard zurückzukehren.",
  "folders.appdataDefault": "appdata (Standard)",
  "folders.stackNote":
    "Dieser Container gehört zum Compose-Stack {stack}. Sein Projektordner wird einmal für den ganzen Stack gesichert, nicht einmal je Dienst, und steht deshalb nicht in dieser Liste.",
  "folders.notReachable": "nicht unter dem Host-Mount, kann nicht gesichert werden",
  "folders.customMissing": "kein Datenordner gefunden (hier gibt es nichts zu sichern)",
  "folders.customPlaceholder": "/mnt/user/irgendein/ordner",
  "folders.addCustom": "Ordnerpfad hinzufügen",
  "folders.add": "Hinzufügen",
  "folders.save": "Ordner speichern",
  "folders.saved": "Gespeichert",
