  "settings.tamperScheduleInactive": "Inaktiv: kein Off-site-Repo ist als append-only markiert, daher läuft dieser Zeitplan nie. Markiere ein Off-site-Repo in dessen Off-site-Einstellungen als append-only, um ihn zu aktivieren.",
  // Gesamt-Backup: ein Durchlauf über alle sechs Domänen, unabhängig von ihren eigenen Zeitplänen
  "settings.everythingTitle": "Gesamt-Backup",
  "settings.everythingHint": "Sichert einmal nacheinander jeden Bereich (Container, VMs, Flash, Ordner, ZFS-Datasets und zuletzt das Selbst-Backup), sodass ein einzelner Ping danach (über den Post-Befehl unten) bestätigt, dass der ganze Server geschützt ist. Standardmäßig aus und unabhängig vom eigenen Zeitplan jedes Bereichs oben.",
  "settings.everythingDuplicateWarning": "Container, VMs, Flash, Ordner, ZFS-Datasets und Selbst-Backup werden doppelt gesichert, solange dieser Zeitplan und ihr eigener gleichzeitig aktiv sind: einmal hier, einmal im eigenen Zeitplan. Schalte die Bereiche ab, die du nicht doppelt sichern willst.",
  "settings.everythingHooksHint": "Diese Befehle laufen auf dem eigenen Server von BombVault über sh -c, nicht in einem Container. Der Pre-Befehl ist best-effort und blockiert den Durchlauf nie; der Post-Befehl feuert immer genau einmal, nachdem jeder Bereich versucht wurde, egal ob einer davon fehlgeschlagen ist.",
  "settings.everythingRunNow": "Gesamt-Backup jetzt starten",
