  "zfs.excludedGone": "Ausgelassen, nicht mehr auf dem Server",
  "zfs.excludes": "Ausschlussmuster",
  "zfs.excludesHint": "Ein Muster pro Zeile. Ein Muster, das mit / beginnt, zählt ab dem Dataset dieses Elements, und ein Unter-Dataset ist ein Ordner mit seinem Namen, zum Beispiel /plex/Library/Cache. Ein Muster ohne / am Anfang trifft in jeder Tiefe und in jedem Dataset, zum Beispiel *.tmp oder Library/Cache. Bei Ordnern ist das anders, dort meint / die Wurzel des Containers.",
