  "zfs.safety.old": "Der älteste Sicherheits-Snapshot ist älter als 30 Tage. Er hält gelöschte und geänderte Daten im Pool fest, bis du ihn löschst.",
  "zfs.safety.hint": "BombVault hat diese Snapshots direkt vor einer Wiederherstellung in ein Dataset angelegt, damit der Stand von davor zurückholbar bleibt. BombVault löscht sie nie von selbst. Einzelne Dateien holst du aus .zfs/snapshot/<name> im Dataset zurück. zfs rollback geht nur, solange es der neueste Snapshot dieses Datasets ist; zfs rollback -r löscht jeden neueren Snapshot, auch die automatischen.",
  "zfs.safety.deleteConfirm": "Sicherheits-Snapshot {name} von {dataset} löschen? Der Stand vor dieser Wiederherstellung ist danach nicht mehr zurückholbar.",
