  // Restore from another BombVault repo — Recovery page (#61 task 11)
  "recovery.foreignTitle": "Aus einem anderen BombVault-Repo wiederherstellen",
  "recovery.foreignIntro": "Hole einzelne Container, VMs, Ordner-Sets oder ZFS-Datasets aus den Backups einer anderen BombVault-Instanz: schreibgeschützt verbinden, Inhalt durchstöbern, Auswahl wiederherstellen. Das andere Repository wird dabei nur gelesen: dort ändert sich nichts, und deine eigenen Backup-Einstellungen bleiben unangetastet.",
  "recovery.foreignStepConnect": "Mit dem anderen Repository verbinden",
  "recovery.foreignStepBrowse": "Durchstöbern & wiederherstellen",
  "recovery.foreignLocation": "Repository-Speicherort",
  "recovery.foreignLocationHint": "Ein Ordner unter dem Host-Mount oder eine restic-Remote-URL (s3:…, rest:…, sftp:…, b2:…). Hänge die Backup-Freigabe des anderen Servers ein und richte dies darauf aus, oder gib sein Remote-Repository direkt an. Bei einem Remote-Repository werden unten dessen eigene Zugangsdaten abgefragt. Ein rclone-Remote wird hier nicht angenommen: Es würde sich mit der rclone-Konfiguration DIESES Servers anmelden, nutze deshalb die native URL des Repositories.",
  "recovery.foreignCredsIntro": "Das sieht nach einem Remote-Repository aus, dafür werden die Zugangsdaten des Backends vom ANDEREN Server gebraucht. Sie gelten nur für diese Sitzung und werden nicht gespeichert. Deine eigenen Off-Site-Zugangsdaten werden hier bewusst nicht wiederverwendet: Sie gingen sonst an eine Adresse, die gerade erst eingetippt wurde.",
  "recovery.foreignS3KeyId": "Zugriffsschlüssel-ID (S3/B2)",
  "recovery.foreignS3Secret": "Geheimer Zugriffsschlüssel (S3/B2)",
  "recovery.foreignS3Region": "Region (optional)",
  "recovery.foreignRestUser": "REST-Benutzername",
  "recovery.foreignRestPassword": "REST-Passwort",
  "recovery.foreignRestHint": "Nur für ein rest:-Repository (einen restic-REST-Server). Bei S3, B2 oder SFTP leer lassen.",
  "recovery.foreignKey": "APP_KEY der anderen Instanz",
  "recovery.foreignKeyHint": "Der 64-stellige Schlüssel aus dem Recovery-Kit der ANDEREN Instanz. Dein eigener Schlüssel bleibt unberührt.",
  "recovery.foreignConnect": "Verbinden",
  "recovery.foreignConnecting": "Verbinde…",
  "recovery.foreignConnected": "Verbunden. Das Repository ist lesbar.",
  "recovery.foreignClose": "Trennen",
  "recovery.foreignNotConnected": "Verbinde dich zuerst oben mit einem Repository.",
  "recovery.foreignEmpty": "Das Repository ist lesbar, enthält aber keine BombVault-Backups.",
  "recovery.foreignDbDumps":
    "one={n} Datenbank-Dump in diesem Repository. Hol ihn dir mit der restic-CLI, wie es das Notfallpaket beschreibt.|other={n} Datenbank-Dumps in diesem Repository. Hol dir einen mit der restic-CLI, wie es das Notfallpaket beschreibt.",
  "recovery.dumpOnlyTitle": "Datenbanken, die nur als Dump gesichert sind",
  "recovery.dumpOnlyHint": "Diese Container haben kein Datei-Backup, nur Datenbank-Dumps. Stelle jeden wieder her und importiere seinen Dump, bevor du die Apps startest, die ihn nutzen.",
  "recovery.restoreAndImport": "Wiederherstellen und importieren",
  "recovery.dumpOnlySkipped":
    "one={n} Datenbank, die nur als Dump gesichert ist, bleibt hier außen vor. Stelle sie über ihre eigene Liste wieder her und importiere sie.|other={n} Datenbanken, die nur als Dump gesichert sind, bleiben hier außen vor. Stelle sie über ihre eigene Liste wieder her und importiere sie.",
  "recovery.foreignLatest": "Neuestes Backup",
  "recovery.foreignTargetFolder": "Zielordner",
  "recovery.foreignWholeSet": "Gesamter Satz",
  "recovery.foreignPickSubfolder": "Unterordner wählen",
  "recovery.foreignSubfolderHint": "Nur die angehakten Unterordner oder Dateien dieses Satzes in den Zielordner wiederherstellen, zum Beispiel einen einzelnen Stack aus einem gesamten Appdata-Backup.",
  "recovery.foreignAppdataDest": "Appdata-Ziel",
  "recovery.foreignAppdataDestHint": "Wohin die Appdata des Containers wiederhergestellt wird. Leer lassen für den Standard. Ein Container, der von einem Pool gesichert wurde, den dieser Server nicht hat (zum Beispiel /mnt/zfs), wird hierher umgemappt und landet so korrekt.",
  "recovery.foreignOverwrite": "Überschreiben, wenn am Ziel bereits Daten liegen",
  "recovery.foreignBindWarning": "Diese Binds zeigen auf Speicher, den dieser Server nicht hat. Appdata wird automatisch umgemappt, aber passe diese nach dem Restore im Container-Template an:",
  "recovery.foreignRestore": "Hierher wiederherstellen",
  "recovery.foreignExistsConfirm": "„{name}“ existiert bereits auf diesem System, daher ÜBERSCHREIBT die Wiederherstellung es mit dem fremden Backup. Fortfahren?",
  "recovery.restoreRowConfirm": "Das neueste Backup von „{name}“ an Ort und Stelle wiederherstellen? Es wird gestoppt, seine aktuellen Daten werden ersetzt, und es bleibt danach gestoppt.",
  "recovery.foreignUnverifiedConfirm": "BombVault konnte die aktuellen Container und VMs dieses Systems nicht auslesen und kann daher nicht feststellen, ob „{name}“ hier bereits existiert. Die Wiederherstellung überschreibt womöglich ein vorhandenes. Fortfahren?",
  "recovery.foreignExpired": "Die Sitzung ist abgelaufen (Sitzungen gelten 30 Minuten). Verbinde dich erneut, um weiterzustöbern.",
