  "mcp.title": "MCP-Server",
  "mcp.hint": "Lässt KI-Assistenten wie Claude über das Model Context Protocol den Sicherungsstand dieses Servers lesen, Backups starten und die selbst gestarteten Backups abbrechen. Wiederherstellungen, Löschungen und Einstellungen bleiben in dieser Weboberfläche.",
  "mcp.statusOff": "Aus: es gibt keinen Schlüssel",
  "mcp.statusOn": "one=An, {n} aktiver Schlüssel|other=An, {n} aktive Schlüssel",
  "mcp.statusNoneWorks": "Aus: kein Schlüssel funktioniert",
  "mcp.noPasswordWarning": "Es ist kein Login-Passwort gesetzt. Damit ist diese Weboberfläche für alle in deinem Netz offen, und wer sie öffnen kann, kann auch einen Schlüssel anlegen.",
  "mcp.setPassword": "Login-Passwort setzen",
  "mcp.needsPasswordForHost": "Diese Seite wurde als {host} geöffnet. Ohne Login-Passwort lassen sich Schlüssel nur von einer IP-Adresse oder einem lokalen Namen wie tower oder tower.local anlegen und ersetzen, damit keine Webseite aus dem Internet einen anlegen kann. Mit einem Login-Passwort fällt diese Einschränkung für diese Adresse weg. Du kannst BombVault auch über seine lokale Adresse öffnen.",
  "mcp.restoreRevokedNotice": "Die Wiederherstellung der Konfiguration hat jeden MCP-Schlüssel widerrufen. Lege neue Schlüssel für deine Assistenten an.",
  "mcp.appKeyChanged": "APP_KEY hat sich seit dem Anlegen dieser Schlüssel geändert, deshalb funktionieren sie nicht mehr. Ersetze jeden Schlüssel und trage ihn in deinen Assistenten nach.",
  "mcp.keyUnusable": "Seit der APP_KEY-Änderung ungültig",
  "mcp.loadFailed": "Die MCP-Schlüssel konnten nicht geladen werden",
  "mcp.endpointLabel": "Endpunkt",
  "mcp.endpointHint": "Die Adresse, mit der sich dein Assistent verbindet. Sie spricht Streamable HTTP und erwartet einen Schlüssel im Authorization- oder X-API-Key-Header; eine OAuth-Anmeldung gibt es nicht.",
  "mcp.newKey": "Neuer Schlüssel",
  "mcp.labelLabel": "Name des Schlüssels",
  "mcp.labelPlaceholder": "Claude Code auf dem Laptop",
  "mcp.allowStart": "Backups starten erlauben",
  "mcp.allowStartHint": "Damit kann der Assistent ein Element, eine ganze Domäne oder alles per Gesamt-Backup sichern und die selbst gestarteten Backups abbrechen: höchstens {n} pro Stunde, {minutes} Minuten Abstand beim selben Element und {perDay} pro Element und Tag. Ein Backup hält laufende Container an, bis es fertig ist. Ohne diese Erlaubnis kann der Schlüssel nur lesen.",
  "mcp.createKey": "Schlüssel anlegen",
  "mcp.created": "Schlüssel angelegt",
  "mcp.labelInvalid": "Gib dem Schlüssel einen Namen mit höchstens 64 Zeichen.",
  "mcp.labelTaken": "Ein aktiver Schlüssel heißt bereits so.",
  "mcp.limitReached": "one=Es gibt bereits {n} aktiven Schlüssel. Widerrufe ihn, bevor du einen neuen anlegst.|other=Es gibt bereits {n} aktive Schlüssel. Widerrufe einen, bevor du einen neuen anlegst.",
  "mcp.newKeyTitle": "Dein neuer Schlüssel",
  "mcp.showOnce": "Kopiere ihn jetzt. BombVault behält nur einen Fingerabdruck davon und kann ihn nicht noch einmal zeigen.",
  "mcp.copyKey": "Schlüssel kopieren",
  "mcp.dismissKey": "Ich habe ihn kopiert",
  "mcp.snippetsLabel": "Client verbinden",
  "mcp.snippetOther": "Andere Clients",
  "mcp.snippetClaudeCodeHint": "Führe das einmal im Terminal aus. Claude Code legt den Schlüssel in deiner Benutzerkonfiguration ab, nicht in einer Projektdatei. Prüfe die Verbindung mit /mcp in Claude Code.",
  "mcp.snippetShellHistory": "Der Befehl enthält den Schlüssel, und deine Shell hebt ihn womöglich in ihrer History auf. Die Dokumentation zeigt eine Form ohne das.",
  "mcp.snippetDesktopHint": "Trage diesen Eintrag in claude_desktop_config.json unter \"mcpServers\" ein (in Claude Desktop: Einstellungen, Entwickler, Konfiguration bearbeiten) und starte Claude Desktop neu. Dafür wird Node.js gebraucht, denn mcp-remote verbindet die Desktop-App mit diesem Server.",
  "mcp.snippetOtherHint": "Jeder Client, der Streamable HTTP spricht, funktioniert. Schick den Schlüssel als Authorization: Bearer oder als X-API-Key.",
  "mcp.snippetOtherCert": "Der Client muss außerdem bombvault-cert.pem vertrauen. Lade die Datei mit dem Knopf neben dem Endpunkt herunter.",
  "mcp.copySnippet": "Ausschnitt kopieren",
  "mcp.tlsHint": "Claude Code und Claude Desktop verbinden sich nur über ein Zertifikat, dem sie trauen. Mit BombVaults eigenem Zertifikat trägst du diese Adresse hier in der Karte nach und lädst es herunter; die Ausschnitte zeigen Node.js dann auf diese Datei. Ein Reverse Proxy oder Tailscale mit vertrautem Zertifikat kommt ohne diesen Schritt aus. HTTP_ONLY stellt die ganze Weboberfläche auf einfaches HTTP um, verlangt eine Änderung an den Container-Einstellungen und schickt den Schlüssel unverschlüsselt. Schalte die Zertifikatsprüfung nie ab. Connectors, die in Claudes eigenen Einstellungen angelegt werden, funktionieren mit BombVault-Schlüsseln nicht, weil sie sich über OAuth anmelden, und das bietet BombVault nicht.",
  "mcp.privacyHint": "Was der Assistent liest, also Namen von Elementen, Laufverlauf, Fehlermeldungen und auffällige Backups, geht an den KI-Anbieter dahinter. BombVault entfernt Host-Pfade, Repository-Orte und Zugangsdaten, bevor etwas das Haus verlässt.",
  "mcp.certNotForThisAddress": "BombVaults Zertifikat nennt {host} nicht, deshalb verweigern Assistenten die Verbindung zu dieser Adresse. Trage die Adresse ins Zertifikat ein und lade es dann für die Ausschnitte herunter.",
  "mcp.certOwnNotForThisAddress": "Dein Zertifikat nennt {host} nicht, deshalb verweigern Assistenten die Verbindung zu dieser Adresse. Verbinde dich über einen Namen, den das Zertifikat abdeckt.",
