  // Anomaly detection over the backup history.
  "nav.anomalies": "Anomalien",
  "anomaly.navCountAria": "Offene kritische Anomalien und Warnungen: {n}",
  "anomaly.title": "Anomalien",
  "anomaly.cardHint": "BombVault vergleicht jedes Backup eines Elements mit den vorherigen und benennt, was nicht dazu passt: viel mehr neue Daten als sonst, ein Neuschreiben der meisten Daten, eine stark geschrumpfte oder gewachsene Quelle, einen kleiner gewordenen Datenbank-Dump, ein Backup, das plötzlich viel länger dauert, wiederholte Fehlschläge, eine Wiederherstellungsprüfung, die nicht mehr besteht, und einen Datenträger, der bald voll ist. Die meisten Prüfungen brauchen erst 10 Backups eines Elements. Ein ZFS-Element wird Dataset für Dataset geprüft, so fällt ein geleertes Unter-Dataset auch in einem großen Baum auf.",
  "anomaly.allClear": "Keine Anomalien in deinen Backups.",
