  "anomaly.acknowledgeHint": "Markiert diese Anomalie als gesehen und schließt sie. Solange die Ursache besteht, wird sie nicht erneut gemeldet; fällt die Ursache weg und tritt später wieder auf, schon. Hält diese Anomalie alte Backups zurück, werden sie ab dem nächsten Aufräumen wieder gelöscht. War die Änderung beabsichtigt, ist „Als erwartet markieren“ die bessere Wahl.",
  "anomaly.expectedHint": "Sagt BombVault, dass die Änderung beabsichtigt war. Eine neue Größe oder Dauer wird nach 10 weiteren Backups zum normalen Niveau, die Prüfung auf eine fast leere Quelle bleibt aktiv. Bei neuen Daten werden Mengen bis zu dieser Größe für dieses Element nicht mehr gemeldet. Hält diese Anomalie alte Backups zurück, werden sie ab dem nächsten Aufräumen wieder gelöscht.",
